-- Generated by scripts/build_compiled.py from src/fraudrules/rules/structuring/st-002-just-below-threshold.yaml. Do not edit.
-- ST-002 Repeated cash deposits just below the reporting threshold
SELECT
  'ST-002' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.customer_id = a.customer_id AND b.ts <= a.ts AND b.ts > a.ts - 1209600
WHERE
  (
    a.channel IN ('cash', 'atm')
    AND a.direction = 'in'
    AND a.txn_type = 'deposit'
    AND a.amount_cents >= 900000
    AND a.amount_cents <= 999999
  )
  AND (
    b.channel IN ('cash', 'atm')
    AND b.direction = 'in'
    AND b.txn_type = 'deposit'
    AND b.amount_cents >= 900000
    AND b.amount_cents <= 999999
  )
GROUP BY
  a.id
HAVING
  COUNT(*) >= 3;
